V C_GraveSleepTests::m_grave(const Args& A) {
    V L_b = A.get(0, SY("b"), nullptr, "grave");
    V L_col = (A.size() > 1 || A.has_kw(SY("col"))) ? A.get(1, SY("col"), nullptr) : V(V(20.0));
    V L_unit;
    pvz::setitem(rdm(rd(pvz::getattr(L_b, SY("avatars")), SV("zombie")), &Obj::玩家位置, SV("玩家位置")), V(0.0), ((L_col + V(12.0)) * pvz::getattr(L_b, SY("tile"))));
    L_unit = callm(L_b, SY("spawn"), Args{SV("zombie:脑光墓碑"), SV("zombie"), (L_col * pvz::getattr(L_b, SY("tile"))), (V(10.0) * pvz::getattr(L_b, SY("tile"))), V(1.0)});
    return V::tuple({L_unit, rd(pvz::getattr(L_b, SY("_native_objects")), rd(L_unit, SV("id")))});
    return V::none();
}

V C_GraveSleepTests::m_test_idle_clock_runs_from_the_first_second_and_rate_falls_linearly(const Args& A) {
    V L_b;
    V L_g;
    V L_unit;
    L_b = m_battle(Args{});
    { V ut1_ = py::as_seq(m_grave(Args{L_b})); L_unit = ut1_.idx(0); L_g = ut1_.idx(1); } 
    (void)(callm(L_b, SY("step"), Args{((V(20.0) * V(30.0)) - V(2.0))}));
    (void)(m_assertFalse(Args{rd(rd(pvz::getattr(L_b, SY("units")), rd(L_unit, SV("id"))), SV("drowsy"))}));
    (void)(m_assertEqual(Args{V(1.0), rdm(L_g, &Obj::_pvp_production_rate, SV("_pvp_production_rate"))}));
    (void)(callm(L_b, SY("step"), Args{V(4.0)}));
    (void)(m_assertTrue(Args{rd(rd(pvz::getattr(L_b, SY("units")), rd(L_unit, SV("id"))), SV("drowsy"))}));
    (void)(callm(L_b, SY("step"), Args{(V(10.0) * V(30.0))}));
    (void)(m_assertAlmostEqual(Args({V(0.75), rdm(L_g, &Obj::_pvp_production_rate, SV("_pvp_production_rate"))}, {{SY("delta"), V(0.01)}})));
    (void)(m_assertAlmostEqual(Args({V(0.5), rd(rd(pvz::getattr(L_b, SY("units")), rd(L_unit, SV("id"))), SV("drowsy_level"))}, {{SY("delta"), V(0.01)}})));
    (void)(callm(L_b, SY("step"), Args{((V(10.0) * V(30.0)) + V(5.0))}));
    (void)(m_assertEqual(Args{V(0.5), rdm(L_g, &Obj::_pvp_production_rate, SV("_pvp_production_rate"))}));
    (void)(m_assertEqual(Args{V(1.0), rd(rd(pvz::getattr(L_b, SY("units")), rd(L_unit, SV("id"))), SV("drowsy_level"))}));
    return V::none();
}

V C_GraveSleepTests::m_test_sleep_multiplies_with_ice_and_deathmatch_clears(const Args& A) {
    V L_b;
    V L_g;
    V L_unit;
    L_b = m_battle(Args{});
    { V ut1_ = py::as_seq(m_grave(Args{L_b})); L_unit = ut1_.idx(0); L_g = ut1_.idx(1); } 
    setm(L_g, &Obj::_pvp_idle, SV("_pvp_idle"), V(45.0));
    setm(L_g, &Obj::冰冻, SV("冰冻"), V(900.0));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertAlmostEqual(Args{V(0.25), rdm(L_g, &Obj::_pvp_production_rate, SV("_pvp_production_rate"))}));
    (void)(callm(L_g, SY("pop"), Args{SV("冰冻"), V::none()}));
    pvz::setattr(L_b, SY("deathmatch"), V(true));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertEqual(Args{V(0.0), rdm(L_g, &Obj::_pvp_idle, SV("_pvp_idle"))}));
    (void)(m_assertEqual(Args{V(1.0), rdm(L_g, &Obj::_pvp_production_rate, SV("_pvp_production_rate"))}));
    return V::none();
}

