V C_ReedTests::m_test_lightning_chains_five_jumps_within_one_tile_and_fires_every_1_5_seconds(const Args& A) {
    V L_b;
    V L_event;
    V L_hits;
    V L_line;
    L_b = m_battle(Args({}, {{SY("plants"), pm_test_pvp_61_features::REEDS}}));
    (void)(m_park_heroes(Args{L_b}));
    (void)(m_reed(Args{L_b}));
    L_line = [&]() -> V { V out_ = V::list(); V L_i; { V it1_ = py::iter_list(py::range((int64_t)(V(8.0)).num())); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_i = it1_.idx(int64_t(i1_)); out_.append(m_held_zombie(Args{L_b, (V(14.0) + (L_i * V(0.8)))})); }}return out_; }();
    (void)(callm(L_b, SY("step"), Args{V(44.0)}));
    (void)(m_assertTrue(Args{[&]() -> V { V L_z; { V it3_ = py::iter_list(L_line); for (size_t i3_ = 0; i3_ < it3_.len(); ++i3_) { L_z = it3_.idx(int64_t(i3_)); if (!((rdm(L_z, &Obj::血量, SV("血量")) == V(50.0)))) return V(false); }}return V(true); }()}));
    (void)(callm(L_b, SY("step"), Args{V(2.0)}));
    L_hits = [&]() -> V { V out_ = V::list(); V L_z; { V it4_ = py::iter_list(L_line); for (size_t i4_ = 0; i4_ < it4_.len(); ++i4_) { L_z = it4_.idx(int64_t(i4_)); out_.append((V(50.0) - rdm(L_z, &Obj::血量, SV("血量")))); }}return out_; }();
    (void)(m_assertEqual(Args{((V::list({V(7.5)}) * V(6.0)) + V::list({V(0.0), V(0.0)})), L_hits}));
    L_event = rd([&]() -> V { V out_ = V::list(); V L_e; { V it5_ = py::iter_list(pvz::getattr(L_b, SY("log"))); for (size_t i5_ = 0; i5_ < it5_.len(); ++i5_) { L_e = it5_.idx(int64_t(i5_)); if (!((py::m_get(L_e, SV("event")) == SV("lightning")))) continue; out_.append(L_e); }}return out_; }(), V(-1.0));
    (void)(m_assertEqual(Args{SV("chain"), rd(L_event, SV("kind"))}));
    (void)(callm(L_b, SY("step"), Args{V(45.0)}));
    (void)(m_assertEqual(Args{V(35.0), rdm(rd(L_line, V(0.0)), &Obj::血量, SV("血量"))}));
    return V::none();
}

