V C_ClownDetonationTests::m_test_owner_detonates_live_clown_through_native_blast(const Args& A) {
    V L_b;
    V L_hp;
    V L_unit;
    V L_z;
    L_b = m_battle(Args({}, {{SY("zombies"), V::list({SV("zombie:脑光墓碑"), SV("zombie:小丑僵尸")})}}));
    (void)(m_park_heroes(Args({L_b}, {{SY("plant_col"), V(14.0)}, {SY("zombie_col"), V(30.0)}})));
    L_unit = callm(L_b, SY("spawn"), Args{SV("zombie:小丑僵尸"), SV("zombie"), (V(14.0) * pvz::getattr(L_b, SY("tile"))), (V(10.0) * pvz::getattr(L_b, SY("tile"))), V(-1.0)});
    L_z = rd(pvz::getattr(L_b, SY("_native_objects")), rd(L_unit, SV("id")));
    setm(L_z, &Obj::出场, SV("出场"), V(500.0));
    setm(L_z, &Obj::黄油, SV("黄油"), pow(V(10.0), V(6.0)));
    L_hp = rdm(rd(pvz::getattr(L_b, SY("avatars")), SV("plant")), &Obj::玩家血量, SV("玩家血量"));
    (void)(m_assertNotEqual(Args{SV(""), m_cmd(Args({L_b, SV("plant"), SV("detonate")}, {{SY("target"), rd(L_unit, SV("id"))}}))}));
    (void)(m_assertNotEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("detonate")}, {{SY("target"), SV("missing")}}))}));
    (void)(m_assertEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("detonate")}, {{SY("target"), rd(L_unit, SV("id"))}}))}));
    (void)(callm(L_b, SY("step"), Args{V(2.0)}));
    (void)(m_assertEqual(Args{V(-1025.0), rdm(L_z, &Obj::血量, SV("血量"))}));
    (void)(m_assertLess(Args{rdm(rd(pvz::getattr(L_b, SY("avatars")), SV("plant")), &Obj::玩家血量, SV("玩家血量")), L_hp}));
    (void)(m_assertNotEqual(Args{SV(""), m_cmd(Args({L_b, SV("zombie"), SV("detonate")}, {{SY("target"), rd(L_unit, SV("id"))}}))}));
    (void)(m_assertEqual(Args{V::list({SV("clown_detonate")}), [&]() -> V { V out_ = V::list(); V L_e; { V it1_ = py::iter_list(pvz::getattr(L_b, SY("log"))); for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) { L_e = it1_.idx(int64_t(i1_)); if (!((py::m_get(L_e, SV("event")) == SV("clown_detonate")))) continue; out_.append(rd(L_e, SV("event"))); }}return out_; }()}));
    return V::none();
}

